entries[12825] = { ["name"] = "Pläne: Loderflammenrapier", ["text"] = "Benötigt Schmiedekunst (280)\nBenötigt Schwertschmiedemeister\nBenutzen: Lehrt Euch die Herstellung eines Loderflammenrapiers.\nLoderflammenrapier\nWird beim Anlegen gebunden\nEinhändig Schwert\n44 - 82 Schaden Tempo 1.70\n(37.06 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nBenötigt Stufe 51\nTrefferchance: Verbrennt den Feind und fügt ihm im Verlauf von 30 Sek. 100 Punkt(e) Schaden zu.\nBenötigt Verzauberter Thoriumbarren (10), Essenz des Feuers (4), Herz des Feuers (4), Azerothianischer Diamant (2), Verdichteter Schleifstein (2)" }
entries[12826] = { ["name"] = "Pläne: Runenschneide", ["text"] = "Benötigt Schmiedekunst (285)\nBenutzen: Lehrt Euch die Herstellung einer Runenschneide.\nRunenschneide\nWird beim Aufheben gebunden\nWaffenhand Axt\n54 - 102 Schaden Tempo 2.30\n(33.91 Schaden pro Sekunde)\n+5 Stärke\n+5 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 52\nBenötigt Thoriumbarren (30), Großer Opal (2), Verdichteter Schleifstein (2), Unverwüstliches Leder (4)" }
entries[12827] = { ["name"] = "Pläne: Beschaulichkeit", ["text"] = "Benötigt Schmiedekunst (285)\nBenötigt Hammerschmiedemeister\nBenutzen: Lehrt Euch die Herstellung von Beschaulichkeit.\nBeschaulichkeit\nWird beim Anlegen gebunden\nWaffenhand Streitkolben\n52 - 98 Schaden Tempo 2.00\n(37.50 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nBenötigt Stufe 52\nTrefferchance: Bannt einen magischen Effekt, der auf dem augenblicklichen Feind liegt.\nBenötigt Verzauberter Thoriumbarren (6), Arkanitbarren (2), Mächtiges Mojo (4), Großer Opal (2), Blauer Saphir (2), Gewaltiger Smaragd" }
entries[12828] = { ["name"] = "Pläne: Vulkanischer Hammer", ["text"] = "Benötigt Schmiedekunst (290)\nBenutzen: Lehrt Euch die Herstellung eines vulkanischen Hammers.\nVulkanischer Hammer\nWird beim Anlegen gebunden\nWaffenhand Streitkolben\n60 - 113 Schaden Tempo 2.50\n(34.60 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 53\nTrefferchance: Schleudert eine glühende Kugel hinaus, die 100 bis 128 Punkt(e) Feuerschaden sowie zusätzlich 6 Sek. lang 18 Punkt(e) Schaden verursacht.\nBenötigt Thoriumbarren (30), Herz des Feuers (4), Sternrubin (4), Unverwüstliches Leder (4)" }
