entries[12830] = { ["name"] = "Pläne: Verderbnis", ["text"] = "Benötigt Schmiedekunst (290)\nBenötigt Schwertschmiedemeister\nBenutzen: Lehrt Euch die Herstellung von Verderbnis.\nVerderbnis\nWird beim Aufheben gebunden\nZweihändig Schwert\n119 - 179 Schaden Tempo 3.00\n(49.67 Schaden pro Sekunde)\n+30 Stärke\n+30 Ausdauer\n-40 Willenskraft\nHaltbarkeit 100 / 100\nBenötigt Stufe 53\nBenötigt Thoriumbarren (40), Arkanitbarren (2), Dämonische Rune (16), Essenz des Untodes (8), Blauer Saphir (2), Verdichteter Schleifstein (2), Unverwüstliches Leder (4)" }
